-- Hosbah queries.

-- name: ListInstallsOfApp :many
-- Team scope: the recipes installed next to an app, by name.
SELECT * FROM app_installs WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') ORDER BY name, id;

-- name: InstallOfApp :one
-- Team scope: one install of an app, by id or by name.
SELECT * FROM app_installs
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') AND (id = sqlc.arg('ref')::text OR name = sqlc.arg('ref')::text)
ORDER BY (id = sqlc.arg('ref')::text) DESC LIMIT 1;

-- name: InsertAppInstall :one
INSERT INTO app_installs (id, team_id, app_id, recipe_id, recipe_version, name, server_id, proxy_host_id, secrets, env_injected, status)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('recipe_id'), sqlc.arg('recipe_version'), sqlc.arg('name'),
    sqlc.arg('server_id'), sqlc.narg('proxy_host_id'), sqlc.arg('secrets'), sqlc.arg('env_injected'), 'creating')
RETURNING *;

-- name: SetAppInstallStatus :execrows
-- Team scope, or the background worker (system + team). from guards the transition.
UPDATE app_installs SET status = sqlc.arg('status'), error = sqlc.narg('error'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND status = sqlc.arg('from')::text;

-- name: SetAppInstallHostPort :execrows
-- The loopback port Docker picked for the install's HTTP port (it changes when the container restarts).
UPDATE app_installs SET host_port = sqlc.narg('host_port'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: DeleteAppInstallInTeam :execrows
DELETE FROM app_installs WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');
